UPDATE game_dont_fill_score
SET level = #{dto.level},
    best_time = #{dto.bestTime},
    cleared_lines = COALESCE(#{dto.clearedLines}, 0),
    achieved_at = NOW()
WHERE user_id = #{userId}
  AND (
    level < #{dto.level}
    OR (level = #{dto.level} AND best_time > #{dto.bestTime})
  )
